def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = tuple(h[1] for h in history)
    me = tuple(h[0] for h in history)

    opp_def = opp.count('D')
    my_def = me.count('D')
    last_me = me[-1]
    last_opp = opp[-1]
    remaining = 100 - n

    # Detect super-cooperative opponent.
    if opp_def == 0:
        # Periodically grab a free defection late, but otherwise keep mutual C.
        if remaining == 0:
            return 'C'
        if n > 40 and n % 12 == 0:
            return 'D'
        return 'C'

    # Detect heavy defector.
    if opp_def * 2 > n:
        # Punish, but occasionally signal willingness to restart.
        if opp_def >= n - 1:
            return 'D'
        if last_opp == 'C' and remaining > 5 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Look at recent opponent behavior over last 12.
    look = 12 if n >= 12 else n
    r_opp = opp[-look:]
    recent_d = r_opp.count('D')

    # Endgame handling: mutually cooperative, grab last rounds.
    if remaining <= 2 and opp_def * 4 < n:
        return 'D'

    # If opponent was highly cooperative in last 12, stay cooperative almost always.
    if recent_d == 0:
        # Probe sparingly to test exploitation resistance.
        if n > 20 and n % 17 == 0:
            return 'D'
        return 'C'
    if recent_d == 1:
        if last_opp == 'D':
            # Retaliate once, then likely forgive.
            return 'D'
        return 'C'

    # Recent moderate defections: tit-for-tat with forgiveness.
    if last_opp == 'D':
        # If we've both been defecting a lot, try a reset.
        if last_me == 'D' and recent_d >= 4:
            if rng.random() < 0.3:
                return 'C'
        # Otherwise punish with high probability.
        if rng.random() < 0.8:
            return 'D'
        return 'C'

    # Opponent cooperated last round: cooperate, unless defection frequency creeping up.
    if recent_d * 2 >= look:
        # Opponent has been defecting half the time recently: mix.
        if n % 5 == 0:
            return 'D'
        return 'C'
    return 'C'
